from collections import Counter

def dot(a,b): return (a&b).bit_count()&1

def basis(xs):
    piv={}
    for x in xs:
        while x:
            i=x.bit_length()-1
            if i not in piv: piv[i]=x; break
            x^=piv[i]
    return tuple(piv.values())

def space(bs):
    s={0}
    for b in bs:s|={a^b for a in s}
    return tuple(sorted(s))

